    13→void UWjWorldCurrencySubsystem::Initialize(FSubsystemCollectionBase& Collection)
    14→{
    15→	Super::Initialize(Collection);
    16→
    17→	// CosmeticSubsystem 의존성 보장
    18→	Collection.InitializeDependency<UWjWorldCosmeticSubsystem>();
    19→
    20→	// CosmeticSubsystem의 인벤토리 갱신 구독
    21→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
    22→	if (CosmeticSub)
    23→	{
    24→		CosmeticSub->OnInventoryUpdated.AddDynamic(this, &UWjWorldCurrencySubsystem::HandleInventoryUpdated);
    25→	}
    26→
    27→	// 로컬 잔액 로드 (비Steam 폴백)
    28→	LoadBalancesFromLocal();
    29→
    30→	UE_LOG(LogWjWorldCurrency, Log, TEXT("CurrencySubsystem 초기화 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
    31→}
