    33→void UWjWorldCurrencySubsystem::Deinitialize()
    34→{
    35→	StopExchangePolling();
    36→	StopGemPurchasePolling();
    37→
    38→	// 로컬 잔액 저장
    39→	SaveBalancesToLocal();
    40→
    41→	// 델리게이트 해제
    42→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
    43→	if (CosmeticSub)
    44→	{
    45→		CosmeticSub->OnInventoryUpdated.RemoveDynamic(this, &UWjWorldCurrencySubsystem::HandleInventoryUpdated);
    46→	}
    47→
    48→#if WITH_STEAM
    49→	ISteamInventory* SteamInv = SteamInventory();
    50→	if (SteamInv)
    51→	{
    52→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
    53→		{
    54→			SteamInv->DestroyResult(ExchangeResultHandle);
    55→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
    56→		}
    57→		if (GemPurchaseResultHandle != k_SteamInventoryResultInvalid)
    58→		{
    59→			SteamInv->DestroyResult(GemPurchaseResultHandle);
    60→			GemPurchaseResultHandle = k_SteamInventoryResultInvalid;
    61→		}
    62→	}
    63→#endif
    64→
    65→	Super::Deinitialize();
    66→}
