   252→bool UWjWorldCurrencySubsystem::PurchaseGemPack(int32 PackDefId)
   253→{
   254→	if (bGemPurchasePending)
   255→	{
   256→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 Gem 팩 구매가 진행 중입니다."));
   257→		return false;
   258→	}
   259→
   260→#if WITH_STEAM
   261→	ISteamInventory* SteamInv = SteamInventory();
   262→	if (!SteamInv)
   263→	{
   264→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Inventory API 사용 불가"));
   265→		return false;
   266→	}
   267→
   268→	// 기존 핸들 정리
   269→	if (GemPurchaseResultHandle != k_SteamInventoryResultInvalid)
   270→	{
   271→		SteamInv->DestroyResult(GemPurchaseResultHandle);
   272→		GemPurchaseResultHandle = k_SteamInventoryResultInvalid;
   273→	}
   274→
   275→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(PackDefId);
   276→	uint32 Quantity = 1;
   277→
   278→	if (SteamInv->StartPurchase(&ItemDef, &Quantity, 1))
   279→	{
   280→		bGemPurchasePending = true;
   281→		StartGemPurchasePolling();
   282→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Gem 팩 구매 요청 시작 (DefId: %d)"), PackDefId);
   283→		return true;
   284→	}
   285→	else
   286→	{
   287→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam StartPurchase 실패 (DefId: %d)"), PackDefId);
   288→		return false;
   289→	}
   290→#else
   291→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매는 Steam 환경에서만 가능합니다."));
   292→	return false;
   293→#endif
   294→}
