   296→void UWjWorldCurrencySubsystem::RefreshBalancesFromInventory()
   297→{
   298→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   299→	if (!Settings)
   300→	{
   301→		return;
   302→	}
   303→
   304→#if WITH_STEAM
   305→	ISteamInventory* SteamInv = SteamInventory();
   306→	if (SteamInv)
   307→	{
   308→		// CosmeticSubsystem의 인벤토리 갱신을 구독하고 있으므로
   309→		// 여기서는 캐시된 인벤토리에서 재화 수량을 파싱
   310→		int32 NewCoinBalance = GetItemQuantityFromInventory(Settings->CoinSteamItemDefId);
   311→		int32 NewGemBalance = GetItemQuantityFromInventory(Settings->GemSteamItemDefId);
   312→
   313→		if (NewCoinBalance != CoinBalance)
   314→		{
   315→			SetBalance(ECurrencyType::Coin, NewCoinBalance);
   316→		}
   317→		if (NewGemBalance != GemBalance)
   318→		{
   319→			SetBalance(ECurrencyType::Gem, NewGemBalance);
   320→		}
   321→
   322→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam 잔액 갱신: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   323→		return;
   324→	}
   325→#endif
   326→
   327→	// 비Steam: 로컬 값 유지
   328→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 잔액: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   329→}
