   331→void UWjWorldCurrencySubsystem::GrantCurrencyLocally(ECurrencyType Type, int32 Amount)
   332→{
   333→	if (Amount <= 0)
   334→	{
   335→		return;
   336→	}
   337→
   338→	int32 CurrentBalance = GetBalance(Type);
   339→	SetBalance(Type, CurrentBalance + Amount);
   340→
   341→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 부여: %s +%d (잔액: %d)"),
   342→		(Type == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   343→		Amount, GetBalance(Type));
   344→}
