   359→int32 UWjWorldCurrencySubsystem::GetItemQuantityFromInventory(int32 SteamItemDefId) const
   360→{
   361→	// CosmeticSubsystem의 캐시된 인벤토리에서 해당 DefId의 수량을 찾음
   362→	// 재화 아이템은 CosmeticCatalog에 등록되어 있지 않으므로
   363→	// CosmeticSubsystem의 파싱에서 "알 수 없는 SteamItemDefId"로 스킵됨
   364→	// 따라서 별도의 Steam Inventory 조회가 필요
   365→
   366→	// 현재는 CosmeticSubsystem의 인벤토리 갱신 시점에 호출되므로
   367→	// 직접 Steam API를 호출하여 확인
   368→#if WITH_STEAM
   369→	ISteamInventory* SteamInv = SteamInventory();
   370→	if (!SteamInv)
   371→	{
   372→		return 0;
   373→	}
   374→
   375→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   376→	if (!SteamInv->GetAllItems(&ResultHandle))
   377→	{
   378→		return 0;
   379→	}
   380→
   381→	// 결과 대기 (동기적 폴링 - 이미 캐시된 경우 즉시 반환)
   382→	// 참고: GetAllItems는 이전에 성공한 결과가 캐시되어 있으면 즉시 반환됨
   383→	int32 TotalQuantity = 0;
   384→
   385→	EResult Status = SteamInv->GetResultStatus(ResultHandle);
   386→	if (Status == k_EResultOK)
   387→	{
   388→		uint32 ItemCount = 0;
   389→		if (SteamInv->GetResultItems(ResultHandle, nullptr, &ItemCount) && ItemCount > 0)
   390→		{
   391→			TArray<SteamItemDetails_t> ItemDetails;
   392→			ItemDetails.SetNum(ItemCount);
   393→
   394→			if (SteamInv->GetResultItems(ResultHandle, ItemDetails.GetData(), &ItemCount))
   395→			{
   396→				for (uint32 i = 0; i < ItemCount; ++i)
   397→				{
   398→					if (ItemDetails[i].m_iDefinition == SteamItemDefId && ItemDetails[i].m_unQuantity > 0)
   399→					{
   400→						TotalQuantity += ItemDetails[i].m_unQuantity;
   401→					}
   402→				}
   403→			}
   404→		}
   405→	}
   406→
   407→	SteamInv->DestroyResult(ResultHandle);
   408→	return TotalQuantity;
   409→#else
   410→	return 0;
   411→#endif
   412→}
