   414→void UWjWorldCurrencySubsystem::PollExchangeResult()
   415→{
   416→#if WITH_STEAM
   417→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   418→	{
   419→		StopExchangePolling();
   420→		return;
   421→	}
   422→
   423→	ISteamInventory* SteamInv = SteamInventory();
   424→	if (!SteamInv)
   425→	{
   426→		StopExchangePolling();
   427→		bExchangePending = false;
   428→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   429→		PendingExchangeItemId = NAME_None;
   430→		return;
   431→	}
   432→
   433→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   434→	if (Status == k_EResultPending)
   435→	{
   436→		return;
   437→	}
   438→
   439→	bool bSuccess = (Status == k_EResultOK);
   440→	if (bSuccess)
   441→	{
   442→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   443→
   444→		// 인벤토리 갱신
   445→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   446→		if (CosmeticSub)
   447→		{
   448→			CosmeticSub->RequestInventoryRefresh();
   449→		}
   450→	}
   451→	else
   452→	{
   453→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   454→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   455→	}
   456→
   457→	SteamInv->DestroyResult(ExchangeResultHandle);
   458→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   459→
   460→	bExchangePending = false;
   461→	OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   462→	PendingExchangeItemId = NAME_None;
   463→
   464→	StopExchangePolling();
   465→#else
   466→	StopExchangePolling();
   467→#endif
   468→}
