   470→void UWjWorldCurrencySubsystem::StartExchangePolling()
   471→{
   472→	UWorld* World = GetWorld();
   473→	if (!World)
   474→	{
   475→		return;
   476→	}
   477→
   478→	World->GetTimerManager().SetTimer(
   479→		ExchangePollTimerHandle,
   480→		this,
   481→		&UWjWorldCurrencySubsystem::PollExchangeResult,
