   534→void UWjWorldCurrencySubsystem::StartGemPurchasePolling()
   535→{
   536→	UWorld* World = GetWorld();
   537→	if (!World)
   538→	{
   539→		return;
   540→	}
   541→
   542→	World->GetTimerManager().SetTimer(
   543→		GemPurchasePollTimerHandle,
   544→		this,
   545→		&UWjWorldCurrencySubsystem::PollGemPurchaseResult,
   546→		1.0f,
   547→		true
   548→	);
   549→}
