   560→void UWjWorldCurrencySubsystem::SaveBalancesToLocal()
   561→{
   562→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CurrencyBalance.ini");
   563→
   564→	GConfig->SetInt(*CurrencyConfigSection, TEXT("CoinBalance"), CoinBalance, ConfigFilePath);
   565→	GConfig->SetInt(*CurrencyConfigSection, TEXT("GemBalance"), GemBalance, ConfigFilePath);
   566→
   567→	GConfig->Flush(false, ConfigFilePath);
