   571→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   572→{
   573→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CurrencyBalance.ini");
   574→
   575→	int32 LoadedCoin = 0;
   576→	int32 LoadedGem = 0;
   577→
   578→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, ConfigFilePath);
   579→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, ConfigFilePath);
   580→
   581→	CoinBalance = FMath::Max(0, LoadedCoin);
   582→	GemBalance = FMath::Max(0, LoadedGem);
   583→
   584→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
