   587→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   588→{
   589→	NewAmount = FMath::Max(0, NewAmount);
   590→
   591→	switch (Type)
   592→	{
   593→	case ECurrencyType::Coin:
   594→		if (CoinBalance != NewAmount)
   595→		{
   596→			CoinBalance = NewAmount;
   597→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   598→		}
   599→		break;
   600→	case ECurrencyType::Gem:
   601→		if (GemBalance != NewAmount)
   602→		{
   603→			GemBalance = NewAmount;
   604→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   605→		}
   606→		break;
   607→	}
   608→}
