   189→void UCosmeticMainWindow::OnActionButtonClicked()
   190→{
   191→	if (SelectedItemId.IsNone())
   192→	{
   193→		return;
   194→	}
   195→
   196→	UGameInstance* GI = GetGameInstance();
   197→	if (!GI)
   198→	{
   199→		return;
   200→	}
   201→
   202→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   203→	if (!CosmeticSub)
   204→	{
   205→		return;
   206→	}
   207→
   208→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   209→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   210→
   211→	if (CurrentMode == ECosmeticWindowMode::Shop)
   212→	{
   213→		// 상점 모드
   214→		if (CosmeticSub->HasItem(SelectedItemId))
   215→		{
   216→			// 보유 중인 아이템 → 장착 또는 해제
   217→			if (EquippedItem == SelectedItemId)
   218→			{
   219→				CosmeticSub->UnequipSlot(CurrentSlot);
   220→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d (from Shop)"), static_cast<int32>(CurrentSlot));
   221→			}
   222→			else
   223→			{
   224→				CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   225→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d (from Shop)"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   226→			}
   227→			CosmeticSub->SaveLoadoutToLocal();
   228→		}
   229→		else
   230→		{
   231→			// 미보유 아이템 → 구매
   232→			UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   233→			if (PurchaseSub && !PurchaseSub->IsPurchasePending())
   234→			{
   235→				PurchaseSub->RequestPurchase(SelectedItemId);
   236→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Purchase requested for %s"), *SelectedItemId.ToString());
   237→			}
   238→		}
   239→	}
   240→	else
   241→	{
   242→		// 인벤토리 모드: 장착 또는 해제
   243→		if (EquippedItem == SelectedItemId)
   244→		{
   245→			CosmeticSub->UnequipSlot(CurrentSlot);
   246→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Unequipped slot %d"), static_cast<int32>(CurrentSlot));
   247→		}
   248→		else
   249→		{
   250→			CosmeticSub->EquipItem(CurrentSlot, SelectedItemId);
   251→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Equipped %s on slot %d"), *SelectedItemId.ToString(), static_cast<int32>(CurrentSlot));
   252→		}
   253→		CosmeticSub->SaveLoadoutToLocal();
   254→	}
   255→}
