   525→void UCosmeticMainWindow::PopulateShopItems()
   526→{
   527→	UGameInstance* GI = GetGameInstance();
   528→	if (!GI)
   529→	{
   530→		return;
   531→	}
   532→
   533→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   534→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   535→	{
   536→		return;
   537→	}
   538→
   539→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   540→	TArray<const FCosmeticItemDefinition*> Items = Catalog->GetItemsBySlot(CurrentSlot);
   541→
   542→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   543→
   544→	int32 Index = 0;
   545→	for (const FCosmeticItemDefinition* ItemDef : Items)
   546→	{
   547→		if (!ItemDef || !ItemDef->IsValid())
   548→		{
   549→			continue;
   550→		}
   551→
   552→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   553→		if (!EntryWidget)
   554→		{
   555→			continue;
   556→		}
   557→
   558→		// 보유/장착 상태 설정
   559→		bool bOwned = CosmeticSub->HasItem(ItemDef->ItemId);
   560→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   561→
   562→		EntryWidget->SetOwned(bOwned);
   563→		EntryWidget->SetEquipped(bEquipped);
   564→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   565→
   566→		// 그리드에 추가
   567→		if (ItemGridPanel)
   568→		{
   569→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   570→		}
   571→
   572→		ItemEntryWidgets.Add(EntryWidget);
   573→		Index++;
   574→	}
   575→
   576→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d shop items"), Index);
   577→}
