   136→FLinearColor UCosmeticItemEntryWidget::GetRarityColor(ECosmeticRarity Rarity) const
   137→{
   138→	switch (Rarity)
   139→	{
   140→	case ECosmeticRarity::Common:
   141→		return FLinearColor(0.5f, 0.5f, 0.5f, 1.f); // 회색
   142→	case ECosmeticRarity::Uncommon:
   143→		return FLinearColor(0.2f, 0.8f, 0.2f, 1.f); // 녹색
   144→	case ECosmeticRarity::Rare:
   145→		return FLinearColor(0.2f, 0.4f, 1.f, 1.f);  // 파랑
   146→	case ECosmeticRarity::Epic:
   147→		return FLinearColor(0.6f, 0.2f, 0.8f, 1.f); // 보라
   148→	case ECosmeticRarity::Legendary:
   149→		return FLinearColor(1.f, 0.6f, 0.f, 1.f);   // 주황
   150→	default:
   151→		return FLinearColor::White;
   152→	}
   153→}
