   155→void UCosmeticItemEntryWidget::OnIconLoaded()
   156→{
   157→	if (!IconLoadHandle.IsValid() || !IconLoadHandle->HasLoadCompleted())
   158→	{
   159→		return;
   160→	}
   161→
   162→	UObject* LoadedAsset = IconLoadHandle->GetLoadedAsset();
   163→	if (UTexture2D* IconTexture = Cast<UTexture2D>(LoadedAsset))
   164→	{
   165→		if (IconImage)
   166→		{
   167→			IconImage->SetBrushFromTexture(IconTexture);
   168→			IconImage->SetColorAndOpacity(FLinearColor::White);
   169→		}
   170→	}
   171→
   172→	IconLoadHandle.Reset();
   173→}
