   324→		}
   325→		if (SelectedItemPriceText)
   326→		{
   327→			SelectedItemPriceText->SetText(FText::GetEmpty());
   328→		}
   329→		return;
   330→	}
   331→
   332→	UGameInstance* GI = GetGameInstance();
   333→	if (!GI)
   334→	{
   335→		return;
   336→	}
   337→
   338→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   339→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   340→	{
   341→		return;
   342→	}
