   360→	if (SelectedItemPriceText)
   361→	{
   362→		if (CosmeticSub->HasItem(SelectedItemId))
   363→		{
   364→			SelectedItemPriceText->SetText(NSLOCTEXT("Cosmetic", "Owned", "보유중"));
   365→		}
   366→		else if (ItemDef->Price > 0)
   367→		{
   368→			SelectedItemPriceText->SetText(FText::Format(NSLOCTEXT("Cosmetic", "PriceFormat", "{0}"), FText::AsNumber(ItemDef->Price)));
