   377→void UCosmeticMainWindow::RefreshActionButton()
   378→{
   379→	if (!ActionButton || !ActionButtonText)
   380→	{
   381→		return;
   382→	}
   383→
   384→	if (SelectedItemId.IsNone())
   385→	{
   386→		ActionButton->SetIsEnabled(false);
   387→		ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "SelectItem", "아이템 선택"));
   388→		return;
   389→	}
   390→
   391→	UGameInstance* GI = GetGameInstance();
   392→	if (!GI)
   393→	{
   394→		return;
   395→	}
   396→
   397→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   398→	if (!CosmeticSub)
   399→	{
   400→		return;
   401→	}
   402→
   403→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   404→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   405→	bool bIsEquipped = (EquippedItem == SelectedItemId);
   406→
   407→	if (CurrentMode == ECosmeticWindowMode::Shop)
   408→	{
   409→		// 상점 모드
   410→		if (CosmeticSub->HasItem(SelectedItemId))
   411→		{
   412→			// 보유 중인 아이템 → 장착/해제 가능
   413→			ActionButton->SetIsEnabled(true);
   414→
   415→			if (bIsEquipped)
   416→			{
   417→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   418→			}
   419→			else
   420→			{
   421→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   422→			}
   423→		}
   424→		else
   425→		{
   426→			// 미보유 아이템 → 구매
   427→			UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>();
   428→			bool bPending = PurchaseSub && PurchaseSub->IsPurchasePending();
   429→
   430→			ActionButton->SetIsEnabled(!bPending);
   431→			ActionButtonText->SetText(bPending
   432→				? NSLOCTEXT("Cosmetic", "Purchasing", "구매 중...")
   433→				: NSLOCTEXT("Cosmetic", "Purchase", "구매"));
   434→		}
   435→	}
   436→	else
   437→	{
   438→		// 인벤토리 모드
   439→		ActionButton->SetIsEnabled(true);
   440→
   441→		if (bIsEquipped)
   442→		{
   443→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   444→		}
   445→		else
   446→		{
   447→			ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   448→		}
   449→	}
   450→}
