   525→void UCosmeticMainWindow::PopulateShopItems()
   526→{
   527→	UGameInstance* GI = GetGameInstance();
   528→	if (!GI)
   529→	{
   530→		return;
   531→	}
   532→
   533→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   534→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   535→	{
   536→		return;
   537→	}
   538→
   539→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   540→	TArray<const FCosmeticItemDefinition*> Items = Catalog->GetItemsBySlot(CurrentSlot);
   541→
   542→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   543→
   544→	int32 Index = 0;
   545→	for (const FCosmeticItemDefinition* ItemDef : Items)
   546→	{
   547→		if (!ItemDef || !ItemDef->IsValid())
   548→		{
   549→			continue;
   550→		}
   551→
   552→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   553→		if (!EntryWidget)
   554→		{
   555→			continue;
   556→		}
   557→
   558→		// 보유/장착 상태 설정
   559→		bool bOwned = CosmeticSub->HasItem(ItemDef->ItemId);
   560→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   561→
   562→		EntryWidget->SetOwned(bOwned);
   563→		EntryWidget->SetEquipped(bEquipped);
   564→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   565→
   566→		// 그리드에 추가
   567→		if (ItemGridPanel)
   568→		{
   569→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   570→		}
   571→
   572→		ItemEntryWidgets.Add(EntryWidget);
   573→		Index++;
   574→	}
   575→
   576→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d shop items"), Index);
   577→}
   578→
   579→void UCosmeticMainWindow::PopulateInventoryItems()
   580→{
   581→	UGameInstance* GI = GetGameInstance();
   582→	if (!GI)
   583→	{
   584→		return;
   585→	}
   586→
   587→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   588→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   589→	{
   590→		return;
   591→	}
   592→
   593→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   594→	const TArray<FCosmeticItemInstance>& Inventory = CosmeticSub->GetInventory();
   595→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   596→
   597→	int32 Index = 0;
   598→	for (const FCosmeticItemInstance& ItemInstance : Inventory)
   599→	{
   600→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(ItemInstance.ItemId);
   601→		if (!ItemDef || !ItemDef->IsValid())
   602→		{
   603→			continue;
   604→		}
   605→
   606→		// 현재 슬롯에 해당하는 아이템만 표시
   607→		if (ItemDef->Slot != CurrentSlot)
   608→		{
   609→			continue;
   610→		}
   611→
   612→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   613→		if (!EntryWidget)
   614→		{
   615→			continue;
   616→		}
   617→
   618→		// 인벤토리 모드에서는 항상 보유 중
   619→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   620→
   621→		EntryWidget->SetOwned(true);
   622→		EntryWidget->SetEquipped(bEquipped);
   623→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   624→
   625→		// 그리드에 추가
   626→		if (ItemGridPanel)
   627→		{
   628→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   629→		}
   630→
   631→		ItemEntryWidgets.Add(EntryWidget);
   632→		Index++;
   633→	}
   634→
   635→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d inventory items"), Index);
   636→}
   637→
   638→UCosmeticItemEntryWidget* UCosmeticMainWindow::CreateItemEntry(const FCosmeticItemDefinition& Def)
   639→{
   640→	if (!ItemEntryWidgetClass)
   641→	{
   642→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CosmeticMainWindow: ItemEntryWidgetClass is not set"));
   643→		return nullptr;
   644→	}
   645→
   646→	UCosmeticItemEntryWidget* EntryWidget = CreateWidget<UCosmeticItemEntryWidget>(GetOwningPlayer(), ItemEntryWidgetClass);
   647→	if (!EntryWidget)
   648→	{
   649→		return nullptr;
   650→	}
   651→
   652→	EntryWidget->SetItemDefinition(Def);
   653→	EntryWidget->OnItemClicked.AddDynamic(this, &UCosmeticMainWindow::OnItemClicked);
   654→
   655→	return EntryWidget;
   656→}
   657→
   658→void UCosmeticMainWindow::ClearItemGrid()
   659→{
   660→	// 델리게이트 바인딩 해제 및 위젯 제거
   661→	for (UCosmeticItemEntryWidget* Entry : ItemEntryWidgets)
   662→	{
   663→		if (Entry)
   664→		{
   665→			Entry->OnItemClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnItemClicked);
   666→			Entry->RemoveFromParent();
   667→		}
   668→	}
   669→	ItemEntryWidgets.Empty();
   670→
   671→	// 그리드 클리어
   672→	if (ItemGridPanel)
   673→	{
   674→		ItemGridPanel->ClearChildren();
   675→	}
   676→}
